sys_ui_action.script:
// bfd_ui_request_card_replacement — issue a replacement card and track it.
(function requestCardReplacementAction() {
    var TASK_TABLE = 'x_1755386_safetr_0_bfd_case_task';

    var task = new GlideRecord(TASK_TABLE);
    task.initialize();
    task.setValue('case', current.getUniqueValue());
    task.setValue('task_type', 'card_replacement');
    task.setValue('status', 'open');
    task.setValue('priority', current.getValue('priority') || 'p3');
    task.setValue('outcome', 'Replacement card requested by ' + gs.getUserDisplayName() + '.');
    if (current.getValue('assigned_group')) task.setValue('assigned_group', current.getValue('assigned_group'));
    if (current.getValue('assigned_agent')) task.setValue('assigned_agent', current.getValue('assigned_agent'));
    var due = new GlideDateTime();
    due.addDaysLocalTime(5);
    task.setValue('due_date', due.getValue());
    task.insert();

    current.setValue('card_action', 'replacement_issued');
    new bfd_TriageEngine().logAiDecision(current, {
        note:
            'Agent requested a card replacement. Fulfilment task ' +
            task.getValue('number') +
            ' raised with a 5 day due date.',
        finalDecision: 'card_action=replacement_issued',
    });
    current.update();

    gs.addInfoMessage(
        'Card replacement requested. An open "Card replacement" task has been added to this case and the action is recorded in the audit trail.'
    );
    action.setRedirectURL(current);
})();
